from hran_pacman.bases.wft_base import WFTDownloader


class CBTSPackageDownloader(WFTDownloader):
    technology = "CBTS"

    @property
    def downloadable_name(self):
        return "{}_release.zip".format(self.baseline)

    @property
    def package_name(self):
        return self.downloadable_name

    def get_site_manager(self):
        """
        Implementation not needed - base class should probably be refactored
        """

    def get_software_package(self):
        """
        Use classic way of downloading package from WFT.
        """
        super(CBTSPackageDownloader, self).get_software_package()
